sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 light;
uniform float reach;
layout(color) uniform half4 color;
uniform float alpha;
uniform float fade;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    float2 l = light * size;
    float shade = 0.0;
    for (int i = 1; i <= 64; i++) {
        float t = float(i) / 64.0;
        float k = 1.0 / (1.0 + reach * t);
        float hit = float(image.eval(l + (coord - l) * k).a) * (1.0 - fade * t);
        shade = max(shade, hit);
    }
    float sa = shade * clamp(alpha, 0.0, 1.0) * float(color.a);
    half4 s = half4(half3(color.rgb) * half(sa), half(sa));
    return src + s * (1.0 - src.a);
}
